import numpy as npimport pandas as pdimport foodomicspy as fdef make_test_dataframe():    return pd.DataFrame(        {            1000.0: [1.0, 2.0, 3.0],            1001.0: [2.0, 4.0, 6.0],            1002.0: [3.0, 6.0, 9.0],        },        index=["sample_1", "sample_2", "sample_3"],    )def test_mean_center_preserves_shape_and_labels():    df = make_test_dataframe()    result = f.preprocessing.mean_center(df)    assert result.shape == df.shape    assert result.index.equals(df.index)    assert result.columns.equals(df.columns)def test_mean_center_column_means_are_zero():    df = make_test_dataframe()    result = f.preprocessing.mean_center(df)    assert np.allclose(result.mean(axis=0), 0.0)def test_snv_preserves_shape_and_labels():    df = make_test_dataframe()    result = f.preprocessing.snv(df)    assert result.shape == df.shape    assert result.index.equals(df.index)    assert result.columns.equals(df.columns)def test_snv_row_means_are_zero():    df = make_test_dataframe()    result = f.preprocessing.snv(df)    assert np.allclose(result.mean(axis=1), 0.0)def test_autoscale_preserves_shape_and_labels():    df = make_test_dataframe()    result = f.preprocessing.autoscale(df)    assert result.shape == df.shape    assert result.index.equals(df.index)    assert result.columns.equals(df.columns)